To create a simple event calendar program, you can use Python with its built-in `datetime` module for handling dates and times. Here's a sample implementation:

```python
from datetime import datetime, timedelta

class Event:
    def __init__(self, title, date):
        self.title = title
        self.date = date

def add_event(events, event_title, event_date):
    event = Event(event_title, event_date)
    events.append(event)

def display_upcoming_events(events):
    upcoming_events = [event for event in events if event.date > datetime.now()]
    if not upcoming_events:
        print("No upcoming events.")
        return

    print("Your upcoming events:")
    for event in upcoming_events:
        print(f"- {event.title} on {event.date.strftime('%Y-%m-%d')}")

def main():
    events = []

    while True:
        command = input("Enter command (add, remove, or display): ").lower()

        if command == "add":
            event_title = input("Enter event title: ")
            event_date = input("Enter event date (YYYY-MM-DD): ")
            add_event(events, event_title, event_date)

        elif command == "remove":
            event_title = input("Enter event title: ")
            for i, event in enumerate(events):
                if event.title == event_title:
                    events.pop(i)
                    break
            else:
                print(f"No event found with title '{event_title}'.")

        elif command == "display":
            display_upcoming_events(events)

        elif command == "quit":
            break

        else:
            print("Invalid command. Please try again.")

if __name__ == "__main__":
    main()
```

This program allows users to add, remove, and display events from the calendar. The `add_event` function adds an event to the list of events, and the `display_upcoming_events` function filters and prints upcoming events based on the current date.
